<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='exceptions';$pageTitle='Exceptions';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];if(fo_has_table($conn,'stipend_schedule_lines')){$s=$conn->prepare("SELECT ss.id schedule_id,ss.schedule_reference,ss.status,sl.* FROM stipend_schedule_lines sl JOIN stipend_schedules ss ON ss.id=sl.schedule_id WHERE ss.created_by=? AND sl.exception_code IS NOT NULL AND sl.exception_code<>'' ORDER BY ss.created_at DESC");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Visible Exceptions</span><h2>Exceptions</h2><p>Calculation exceptions stay attached to schedules and cannot be silently hidden.</p></div></div><div class="fo-card"><div class="fo-table-wrap"><table><thead><tr><th>Schedule</th><th>Participant</th><th>Approved Minutes</th><th>Amount</th><th>Exception</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><strong><?= e($x['schedule_reference']) ?></strong></td><td><?= e($x['participant_name_snapshot']) ?></td><td><?= number_format((int)$x['approved_minutes']) ?></td><td><?= e(fo_money($x['gross_amount'])) ?></td><td><span class="fo-status fo-status--danger"><?= e($x['exception_message']) ?></span></td><td><?= e(fo_label($x['status'])) ?></td><td><a class="fo-icon-btn" href="<?= url('finance_officer/schedule_view.php?id='.(int)$x['schedule_id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="fo-empty"><i class="fas fa-circle-check"></i><strong>No exceptions found</strong></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>